import base64, os

def read(p):
    with open(p, encoding="utf-8") as f:
        return f.read()

def write(p, s):
    with open(p, "w", encoding="utf-8", newline="\n") as f:
        f.write(s)

if os.path.exists(".den_logo_applied"):
    raise SystemExit("deja applique")

