# verifications avant d'ecrire quoi que ce soit
colors = "src/android/app/src/main/res/values/colors.xml"
cs = read(colors)
old_color = "<color name='ic_launcher_background'>#1F143C</color>"
if cs.count(old_color) != 1:
    raise SystemExit("ANCRE INTROUVABLE (colors.xml)")
rd = read("README.md")
old_title = "# Eden Nextendo\n"
if rd.count(old_title) != 1:
    raise SystemExit("ANCRE INTROUVABLE (README.md): applique d'abord apply_readme.py")
for dst in BLOBS:
    if dst.startswith("src/") and not os.path.exists(dst):
        raise SystemExit("fichier introuvable : " + dst)

for dst, b in BLOBS.items():
    os.makedirs(os.path.dirname(dst), exist_ok=True)
    with open(dst, "wb") as f:
        f.write(base64.b64decode(b))
    print("ecrit", dst)

write(colors, cs.replace(old_color, "<color name='ic_launcher_background'>#07140D</color>"))
write("README.md", rd.replace(old_title,
    '<p align="center"><img src="./dist/den-logo.png" alt="DEN" width="160"></p>\n\n# DEN \u2014 Eden Nextendo\n'))

open(".den_logo_applied", "w").write("ok\n")
print("TERMINE")
